2328	static int get_hall_number_from_symmetry(int const rotation[][3][3],
2329	                                         double const translation[][3],
2330	                                         int const num_operations,
2331	                                         double const lattice[3][3],
2332	                                         int const transform_lattice_by_tmat,
2333	                                         double const symprec) {
2334	    int i, hall_number;
2335	    Symmetry *symmetry;
2336	    Symmetry *prim_symmetry;
2337	    Spacegroup *spacegroup;
2338	    double t_mat[3][3], t_mat_inv[3][3], prim_lat[3][3];
2339	
2340	    symmetry = NULL;
2341	    prim_symmetry = NULL;
2342	    spacegroup = NULL;
2343	
2344	    if ((symmetry = sym_alloc_symmetry(num_operations)) == NULL) {
2345	        goto err;
2346	    }
2347	
2348	    for (i = 0; i < num_operations; i++) {
2349	        mat_copy_matrix_i3(symmetry->rot[i], rotation[i]);
2350	        mat_copy_vector_d3(symmetry->trans[i], translation[i]);
2351	    }
2352	
2353	    prim_symmetry = prm_get_primitive_symmetry(t_mat, symmetry, symprec);
2354	    sym_free_symmetry(symmetry);
2355	    symmetry = NULL;
2356	
2357	    if (prim_symmetry == NULL) {
2358	        goto err;
2359	    }
2360	
2361	    if (transform_lattice_by_tmat) {
2362	        if (!mat_inverse_matrix_d3(t_mat_inv, t_mat, symprec)) {
2363	            goto err;
2364	        }
2365	        mat_multiply_matrix_d3(prim_lat, lattice, t_mat_inv);
2366	    } else {
2367	        mat_copy_matrix_d3(prim_lat, lattice);
2368	    }
2369	
2370	    spacegroup =
2371	        spa_search_spacegroup_with_symmetry(prim_symmetry, prim_lat, symprec);
2372	    sym_free_symmetry(prim_symmetry);
2373	    prim_symmetry = NULL;
2374	    if (spacegroup) {
2375	        hall_number = spacegroup->hall_number;
2376	        free(spacegroup);
2377	        spacegroup = NULL;
2378	    } else {
2379	        goto err;
2380	    }
2381	
2382	    return hall_number;
2383	
2384	err:
2385	    return 0;

