143	// t_mat transforms primitive cell to conventional:
144	// (a_p, b_p, c_p) t_mat = (a_c, b_c, c_c)
145	// If failed, return NULL
146	Symmetry *prm_get_primitive_symmetry(double t_mat[3][3],
147	                                     Symmetry const *symmetry,
148	                                     double const symprec) {
149	    int i, primsym_size;
150	    VecDBL *pure_trans;
151	    Symmetry *prim_symmetry;
152	    double t_mat_inv[3][3], tmp_mat[3][3];
153	
154	    pure_trans = NULL;
155	    prim_symmetry = NULL;
156	
157	    if ((pure_trans = collect_pure_translations(symmetry)) == NULL) {
158	        return NULL;
159	    }
160	    primsym_size = symmetry->size / pure_trans->size;
161	
162	    /* t_mat: T=(Lp^-1.L) where L is identity matrix. */
163	    if (get_primitive_in_translation_space(t_mat_inv, pure_trans,
164	                                           symmetry->size, symprec) == 0) {
165	        mat_free_VecDBL(pure_trans);
166	        pure_trans = NULL;
167	        return NULL;
168	    }
169	
170	    mat_free_VecDBL(pure_trans);
171	    pure_trans = NULL;
172	
173	    if (!mat_inverse_matrix_d3(t_mat, t_mat_inv, symprec)) {
174	        return NULL;
175	    }
176	
177	    /* Collect operations for primitive cell from operations in 'symmetry' */
178	    if ((prim_symmetry = collect_primitive_symmetry(symmetry, primsym_size)) ==
179	        NULL) {
180	        return NULL;
181	    }
182	
183	    /* Overwrite prim_symmetry by (T, 0) (R, t) (T, 0)^-1 = (T R T^-1, T t) */
184	    for (i = 0; i < prim_symmetry->size; i++) {
185	        mat_multiply_matrix_di3(tmp_mat, t_mat, prim_symmetry->rot[i]);
186	        mat_multiply_matrix_d3(tmp_mat, tmp_mat, t_mat_inv);
187	        mat_cast_matrix_3d_to_3i(prim_symmetry->rot[i], tmp_mat);
188	        mat_multiply_matrix_vector_d3(prim_symmetry->trans[i], t_mat,
189	                                      prim_symmetry->trans[i]);
190	    }
191	
192	    for (i = 0; i < prim_symmetry->size; i++) {
193	        debug_print("--- %d ---\n", i + 1);
194	        for (int j = 0; j < 3; j++) {
195	            debug_print("%d %d %d\n", prim_symmetry->rot[i][j][0],
196	                        prim_symmetry->rot[i][j][1],
197	                        prim_symmetry->rot[i][j][2]);
198	        }
199	        debug_print("%f %f %f\n", prim_symmetry->trans[i][0],
200	                    prim_symmetry->trans[i][1], prim_symmetry->trans[i][2]);
201	    }
202	
203	    return prim_symmetry;
204	}
