265	/* Return NULL if failed */
266	static Cell *get_cell_with_smallest_lattice(Cell const *cell,
267	                                            double const symprec) {
268	    int i, j, aperiodic_axis;
269	    double min_lat[3][3], trans_mat[3][3], inv_lat[3][3];
270	    Cell *smallest_cell;
271	
272	    debug_print("get_cell_with_smallest_lattice:\n");
273	
274	    smallest_cell = NULL;
275	
276	    aperiodic_axis = cell->aperiodic_axis;
277	    if ((aperiodic_axis == -1 &&
278	         !del_delaunay_reduce(min_lat, cell->lattice, symprec)) ||
279	        (aperiodic_axis != -1 &&
280	         !del_layer_delaunay_reduce(min_lat, cell->lattice, aperiodic_axis,
281	                                    symprec))) {
282	        return NULL;
283	    }
284	
285	    mat_inverse_matrix_d3(inv_lat, min_lat, 0);
286	    mat_multiply_matrix_d3(trans_mat, inv_lat, cell->lattice);
287	
288	    if ((smallest_cell = cel_alloc_cell(cell->size, cell->tensor_rank)) ==
289	        NULL) {
290	        return NULL;
291	    }
292	
293	    mat_copy_matrix_d3(smallest_cell->lattice, min_lat);
294	    for (i = 0; i < cell->size; i++) {
295	        smallest_cell->types[i] = cell->types[i];
296	        mat_multiply_matrix_vector_d3(smallest_cell->position[i], trans_mat,
297	                                      cell->position[i]);
298	        for (j = 0; j < 3; j++) {
299	            if (j == aperiodic_axis) {
300	                smallest_cell->aperiodic_axis = j;
301	            } else {
302	                smallest_cell->position[i][j] =
303	                    mat_Dmod1(smallest_cell->position[i][j]);
304	            }
305	        }
306	    }
307	
308	    return smallest_cell;
309	}
