311	/* Return NULL if failed */
312	static Cell *get_primitive_cell(int *mapping_table, Cell const *cell,
313	                                VecDBL const *pure_trans, double const symprec,
314	                                double const angle_tolerance) {
315	    int multi;
316	    double prim_lattice[3][3];
317	    Cell *primitive_cell;
318	
319	    debug_print("get_primitive_cell:\n");
320	
321	    primitive_cell = NULL;
322	
323	    /* Primitive lattice vectors are searched. */
324	    /* To be consistent, sometimes tolerance is decreased iteratively. */
325	    /* The decreased tolerance is stored in 'static double tolerance'. */
326	    multi = get_primitive_lattice_vectors(prim_lattice, cell, pure_trans,
327	                                          symprec, angle_tolerance);
328	    if (!multi) {
329	        goto not_found;
330	    }
331	
332	    /* Fit atoms into new primitive cell */
333	    if ((primitive_cell = cel_trim_cell(mapping_table, prim_lattice, cell,
334	                                        symprec)) == NULL) {
335	        goto not_found;
336	    }
337	
338	    /* found */
339	    return primitive_cell;
340	
341	not_found:
342	    debug_print("spglib: Primitive cell could not be found\n");
343	    return NULL;
344	}
