346	/* Return 0 if failed */
347	static int get_primitive_lattice_vectors(double prim_lattice[3][3],
348	                                         Cell const *cell,
349	                                         VecDBL const *pure_trans,
350	                                         double const symprec,
351	                                         double const angle_tolerance) {
352	    int i, multi, attempt;
353	    double tolerance;
354	    VecDBL *vectors, *pure_trans_reduced, *tmp_vec;
355	
356	    vectors = NULL;
357	    pure_trans_reduced = NULL;
358	    tmp_vec = NULL;
359	
360	    tolerance = symprec;
361	
362	    if ((pure_trans_reduced = mat_alloc_VecDBL(pure_trans->size)) == NULL) {
363	        goto fail;
364	    }
365	
366	    for (i = 0; i < pure_trans->size; i++) {
367	        mat_copy_vector_d3(pure_trans_reduced->vec[i], pure_trans->vec[i]);
368	    }
369	
370	    for (attempt = 0; attempt < NUM_ATTEMPT; attempt++) {
371	        multi = pure_trans_reduced->size;
372	
373	        if ((vectors = get_translation_candidates(pure_trans_reduced)) ==
374	            NULL) {
375	            mat_free_VecDBL(pure_trans_reduced);
376	            pure_trans_reduced = NULL;
377	            goto fail;
378	        }
379	
380	        /* Lattice of primitive cell is found among pure translation vectors */
381	        if (find_primitive_lattice_vectors(prim_lattice, vectors, cell,
382	                                           tolerance)) {
383	            mat_free_VecDBL(vectors);
384	            vectors = NULL;
385	            mat_free_VecDBL(pure_trans_reduced);
386	            pure_trans_reduced = NULL;
387	
388	            if ((cell->aperiodic_axis == -1 &&
389	                 !del_delaunay_reduce(prim_lattice, prim_lattice, symprec)) ||
390	                (cell->aperiodic_axis != -1 &&
391	                 !del_layer_delaunay_reduce(prim_lattice, prim_lattice,
392	                                            cell->aperiodic_axis, symprec))) {
393	                goto fail;
394	            }
395	
396	            goto found;
397	
398	        } else {
399	            if ((tmp_vec = mat_alloc_VecDBL(multi)) == NULL) {
400	                mat_free_VecDBL(vectors);
401	                vectors = NULL;
402	                mat_free_VecDBL(pure_trans_reduced);
403	                pure_trans_reduced = NULL;
404	                goto fail;
405	            }
406	
407	            for (i = 0; i < multi; i++) {
408	                mat_copy_vector_d3(tmp_vec->vec[i], pure_trans_reduced->vec[i]);
409	            }
410	            mat_free_VecDBL(pure_trans_reduced);
411	            pure_trans_reduced = NULL;
412	
413	            pure_trans_reduced = sym_reduce_pure_translation(
414	                cell, tmp_vec, tolerance, angle_tolerance);
415	
416	            mat_free_VecDBL(tmp_vec);
417	            tmp_vec = NULL;
418	            mat_free_VecDBL(vectors);
419	            vectors = NULL;
420	
421	            if (pure_trans_reduced == NULL) {
422	                goto fail;
423	            }
424	
425	            debug_print("spglib: Tolerance is reduced to %f (%d), ", tolerance,
426	                        attempt);
427	            debug_print("num_pure_trans = %d\n", pure_trans_reduced->size);
428	
429	            tolerance *= REDUCE_RATE;
430	        }
431	    }
432	
433	    mat_free_VecDBL(pure_trans_reduced);
434	    pure_trans_reduced = NULL;
435	
436	fail:
437	    return 0;
438	
439	found:
440	    return multi;
441	}
