544	static VecDBL *get_translation_candidates(VecDBL const *pure_trans) {
545	    int i, j, multi;
546	    VecDBL *vectors;
547	
548	    vectors = NULL;
549	    multi = pure_trans->size;
550	
551	    if ((vectors = mat_alloc_VecDBL(multi + 2)) == NULL) {
552	        return NULL;
553	    }
554	
555	    /* store pure translations in original cell */
556	    /* as trial primitive lattice vectors */
557	    for (i = 0; i < multi - 1; i++) {
558	        mat_copy_vector_d3(vectors->vec[i], pure_trans->vec[i + 1]);
559	    }
560	
561	    /* store lattice translations of original cell */
562	    /* as trial primitive lattice vectors */
563	    for (i = 0; i < 3; i++) {
564	        for (j = 0; j < 3; j++) {
565	            if (i == j) {
566	                vectors->vec[i + multi - 1][j] = 1;
567	            } else {
568	                vectors->vec[i + multi - 1][j] = 0;
569	            }
570	        }
571	    }
572	
573	    return vectors;
574	}
