674	                                            int const primsym_size) {
675	    int i, j, num_psym, is_found;
676	    Symmetry *prim_symmetry;
677	
678	    prim_symmetry = NULL;
679	
680	    prim_symmetry = sym_alloc_symmetry(primsym_size);
681	    num_psym = 1;
682	    mat_copy_matrix_i3(prim_symmetry->rot[0], symmetry->rot[0]);
683	    mat_copy_vector_d3(prim_symmetry->trans[0], symmetry->trans[0]);
684	    for (i = 1; i < symmetry->size; i++) {
685	        is_found = 1;
686	        for (j = 0; j < num_psym; j++) {
687	            if (mat_check_identity_matrix_i3(prim_symmetry->rot[j],
688	                                             symmetry->rot[i])) {
689	                is_found = 0;
690	                break;
691	            }
692	        }
693	        if (is_found) {
694	            if (num_psym == primsym_size) {
695	                sym_free_symmetry(prim_symmetry);
696	                prim_symmetry = NULL;
697	                break;
698	            }
699	            mat_copy_matrix_i3(prim_symmetry->rot[num_psym], symmetry->rot[i]);
700	            mat_copy_vector_d3(prim_symmetry->trans[num_psym],
701	                               symmetry->trans[i]);
702	            num_psym++;
703	        }
704	    }
705	
706	    if (prim_symmetry == NULL) {
707	        return NULL;
708	    }
709	
710	    if (num_psym != primsym_size) {
711	        sym_free_symmetry(prim_symmetry);
712	        prim_symmetry = NULL;
713	        return NULL;
714	    }
715	
716	    return prim_symmetry;
717	}

