570	Cell *spa_transform_from_primitive(Cell const *primitive,
571	                                   Centering const centering,
572	                                   double const symprec) {
573	    int multi, i, j, k, num_atom;
574	    int *mapping_table;
575	    double tmat[3][3], inv_tmat[3][3], shift[3][3];
576	    Cell *std_cell, *trimmed_cell;
577	
578	    mapping_table = NULL;
579	    trimmed_cell = NULL;
580	    std_cell = NULL;
581	
582	    switch (centering) {
583	        case PRIMITIVE:
584	            break;
585	        case A_FACE:
586	            mat_copy_matrix_d3(tmat, A_mat);
587	            mat_inverse_matrix_d3(inv_tmat, A_mat, 0);
588	            break;
589	        case C_FACE:
590	            mat_copy_matrix_d3(tmat, C_mat);
591	            mat_inverse_matrix_d3(inv_tmat, C_mat, 0);
592	            break;
593	        case FACE:
594	            mat_copy_matrix_d3(tmat, F_mat);
595	            mat_inverse_matrix_d3(inv_tmat, F_mat, 0);
596	            break;
597	        case BODY:
598	            mat_copy_matrix_d3(tmat, I_mat);
599	            mat_inverse_matrix_d3(inv_tmat, I_mat, 0);
600	            break;
601	        case R_CENTER:
602	            mat_copy_matrix_d3(tmat, R_mat);
603	            mat_inverse_matrix_d3(inv_tmat, R_mat, 0);
604	            break;
605	        default:
606	            goto ret;
607	    }
608	
609	    multi = get_centering_shifts(shift, centering);
610	
611	    if ((mapping_table =
612	             (int *)malloc(sizeof(int) * primitive->size * multi)) == NULL) {
613	        warning_memory("mapping_table");
614	        goto ret;
615	    }
616	
617	    if ((std_cell = cel_alloc_cell(primitive->size * multi,
618	                                   primitive->tensor_rank)) == NULL) {
619	        free(mapping_table);
620	        mapping_table = NULL;
621	        goto ret;
622	    }
623	
624	    mat_multiply_matrix_d3(std_cell->lattice, primitive->lattice, inv_tmat);
625	
626	    num_atom = 0;
627	    for (i = 0; i < primitive->size; i++) {
628	        mat_multiply_matrix_vector_d3(std_cell->position[num_atom], tmat,
629	                                      primitive->position[i]);
630	        std_cell->types[num_atom] = primitive->types[i];
631	        num_atom++;
632	    }
633	
634	    for (i = 0; i < multi - 1; i++) {
635	        for (j = 0; j < primitive->size; j++) {
636	            mat_copy_vector_d3(std_cell->position[num_atom],
637	                               std_cell->position[j]);
638	            for (k = 0; k < 3; k++) {
639	                std_cell->position[num_atom][k] += shift[i][k];
640	            }
641	            std_cell->types[num_atom] = std_cell->types[j];
642	            num_atom++;
643	        }
644	    }
645	
646	    trimmed_cell =
647	        cel_trim_cell(mapping_table, std_cell->lattice, std_cell, symprec);
648	    cel_free_cell(std_cell);
649	    std_cell = NULL;
650	    free(mapping_table);
651	    mapping_table = NULL;
652	
653	ret:
654	    return trimmed_cell;
655	}
