672	static Spacegroup *search_spacegroup_with_symmetry(
673	    Primitive const *primitive, int const candidates[],
674	    int const num_candidates, Symmetry const *symmetry, double const symprec,
675	    double const angle_tolerance) {
676	    int hall_number;
677	    double conv_lattice[3][3];
678	    double origin_shift[3];
679	    Spacegroup *spacegroup;
680	    PointSymmetry pointsym;
681	
682	    debug_print("search_spacegroup (tolerance = %f):\n", symprec);
683	
684	    spacegroup = NULL;
685	    origin_shift[0] = 0;
686	    origin_shift[1] = 0;
687	    origin_shift[2] = 0;
688	
689	    pointsym = ptg_get_pointsymmetry(symmetry->rot, symmetry->size);
690	    if (pointsym.size < symmetry->size) {
691	        info_print("spglib: Point symmetry of primitive cell is broken.\n");
692	        return NULL;
693	    }
694	
695	    hall_number = iterative_search_hall_number(
696	        origin_shift, conv_lattice, candidates, num_candidates, primitive,
697	        symmetry, symprec, angle_tolerance);
698	    if (hall_number == 0) {
699	        return NULL;
700	    }
701	
702	    spacegroup = get_spacegroup(hall_number, origin_shift, conv_lattice);
703	
704	    return spacegroup;
