788	/* Return 0 if failed */
789	static int search_hall_number(double origin_shift[3], double conv_lattice[3][3],
790	                              int const candidates[], int const num_candidates,
791	                              Primitive const *primitive,
792	                              Symmetry const *symmetry, double const symprec) {
793	    int i, hall_number, aperiodic_axis;
794	    Centering centering;
795	    Pointgroup pointgroup;
796	    Symmetry *conv_symmetry;
797	    int tmat_int[3][3];
798	    double correction_mat[3][3], tmat[3][3], conv_lattice_tmp[3][3];
799	
800	    debug_print("search_hall_number:\n");
801	
802	    hall_number = 0;
803	    conv_symmetry = NULL;
804	
805	    aperiodic_axis = primitive->cell->aperiodic_axis;
806	
807	    /* primitive->cell->lattice is set right handed. */
808	    /* tmat_int is set right handed. */
809	
810	    /* For rhombohedral system, basis vectors for hP */
811	    /* (hexagonal lattice basis) are provided by tmat_int, */
812	    /* but may be either obverse or reverse setting. */
813	    pointgroup = ptg_get_transformation_matrix(tmat_int, symmetry->rot,
814	                                               symmetry->size, aperiodic_axis);
815	
816	    debug_print("initial transformation matrix\n");
817	    debug_print_matrix_i3(tmat_int);
818	
819	    if (pointgroup.number == 0) {
820	        goto err;
821	    }
822	
823	    /* For LAUE1 and LAUE2M, update tmat_int by making smallest lattice */
824	    if (pointgroup.laue == LAUE1 || pointgroup.laue == LAUE2M) {
825	        mat_multiply_matrix_di3(conv_lattice_tmp, primitive->cell->lattice,
826	                                tmat_int);
827	
828	        if (pointgroup.laue == LAUE1) {
829	            if (!change_basis_tricli(tmat_int, conv_lattice_tmp,
830	                                     primitive->cell->lattice, symprec,
831	                                     aperiodic_axis)) {
832	                goto err;
833	            }
834	        }
835	
836	        /* The angle between non-unique axes may be acute or non-acute. */
837	        if (pointgroup.laue == LAUE2M) {
838	            if (!change_basis_monocli(tmat_int, conv_lattice_tmp,
839	                                      primitive->cell->lattice, symprec,
840	                                      aperiodic_axis)) {
841	                goto err;
842	            }
843	        }
844	    }
845	
846	    /* For rhombohedral system, correction matrix to hR */
847	    /* (a=b=c primitive lattice basis) is returned judging */
848	    /* either obverse or reverse setting. centering=R_CENTER. */
849	    if ((centering = get_centering(correction_mat, tmat_int,
850	                                   pointgroup.laue)) == CENTERING_ERROR) {
851	        goto err;
852	    }
853	
854	    mat_multiply_matrix_id3(tmat, tmat_int, correction_mat);
855	    mat_multiply_matrix_d3(conv_lattice, primitive->cell->lattice, tmat);
856	
857	    debug_print("transformation matrix\n");
858	    debug_print_matrix_d3(tmat);
859	
860	    /* For rhombohedral system, symmetry for a=b=c primitive lattice */
861	    /* basis is returned although centering == R_CENTER. */
862	    if ((conv_symmetry = get_initial_conventional_symmetry(centering, tmat,
863	                                                           symmetry)) == NULL) {
864	        goto err;
865	    }
866	
867	    for (i = 0; i < num_candidates; i++) {
868	        /* Check if hall_number is that of rhombohedral. */
869	        if (match_hall_symbol_db(
870	                origin_shift, conv_lattice, /* <-- modified only matched */
871	                primitive->orig_lattice, candidates[i], pointgroup.number,
872	                pointgroup.holohedry, centering, conv_symmetry, symprec)) {
873	            debug_print("origin shift\n");
874	            debug_print_vector_d3(origin_shift);
875	
876	            hall_number = candidates[i];
877	            break;
878	        }
879	    }
880	
881	    sym_free_symmetry(conv_symmetry);
882	    conv_symmetry = NULL;
883	
884	    return hall_number;
885	
886	err:
887	    return 0;
888	}
