890	// Perform Niggli cell reduction for Triclinic. Return 0 if failed.
891	static int change_basis_tricli(int tmat_int[3][3],
892	                               double const conv_lattice[3][3],
893	                               double const primitive_lattice[3][3],
894	                               double const symprec, int const aperiodic_axis) {
895	    int i, j;
896	    double niggli_cell[9];
897	    double smallest_lattice[3][3], inv_lattice[3][3], tmat[3][3];
898	
899	    for (i = 0; i < 3; i++) {
900	        for (j = 0; j < 3; j++) {
901	            niggli_cell[i * 3 + j] = conv_lattice[i][j];
902	        }
903	    }
904	
905	    if (!niggli_reduce(niggli_cell, symprec * symprec, aperiodic_axis)) {
906	        return 0;
907	    }
908	
909	    for (i = 0; i < 3; i++) {
910	        for (j = 0; j < 3; j++) {
911	            smallest_lattice[i][j] = niggli_cell[i * 3 + j];
912	        }
913	    }
914	    if (mat_get_determinant_d3(smallest_lattice) < 0) {
915	        for (i = 0; i < 3; i++) {
916	            for (j = 0; j < 3; j++) {
917	                smallest_lattice[i][j] = -smallest_lattice[i][j];
918	            }
919	        }
920	    }
921	    mat_inverse_matrix_d3(inv_lattice, primitive_lattice, 0);
922	    mat_multiply_matrix_d3(tmat, inv_lattice, smallest_lattice);
923	    mat_cast_matrix_3d_to_3i(tmat_int, tmat);
924	
925	    return 1;
926	}
