928	/* Monoclinic: choose shortest a, c lattice vectors (|a| < |c|) */
929	/* Return 0 if failed */
930	static int change_basis_monocli(int tmat_int[3][3],
931	                                double const conv_lattice[3][3],
932	                                double const primitive_lattice[3][3],
933	                                double const symprec,
934	                                int const aperiodic_axis_prim) {
935	    double smallest_lattice[3][3], inv_lattice[3][3], tmat[3][3];
936	    int i, aperiodic_axis_conv, unique_axis;
937	
938	    /* Unique axis of 3D monoclinic crystal system is b */
939	    /* For layer with 2D op/oc lattice, unique axis is a */
940	    if (aperiodic_axis_prim == -1) {
941	        aperiodic_axis_conv = -1;
942	        unique_axis = 1;
943	    } else {
944	        for (i = 0; i < 3; i++) {
945	            if (tmat_int[aperiodic_axis_prim][i] != 0) {
946	                aperiodic_axis_conv = i;
947	            }
948	        }
949	        unique_axis = 0;
950	    }
951	
952	    if (!del_layer_delaunay_reduce_2D(smallest_lattice, conv_lattice,
953	                                      unique_axis, aperiodic_axis_conv,
954	                                      symprec)) {
955	        return 0;
956	    }
957	
958	    /* For layer with 2D mp lattice, move the unique axis to c */
959	    if (aperiodic_axis_conv == 0) {
960	        mat_multiply_matrix_d3(smallest_lattice, smallest_lattice,
961	                               change_of_basis_monocli[2]);
962	    }
963	
964	    mat_inverse_matrix_d3(inv_lattice, primitive_lattice, 0);
965	    mat_multiply_matrix_d3(tmat, inv_lattice, smallest_lattice);
966	    mat_cast_matrix_3d_to_3i(tmat_int, tmat);
967	    return 1;
968	}
