971	static Symmetry *get_initial_conventional_symmetry(Centering const centering,
972	                                                   double const tmat[3][3],
973	                                                   Symmetry const *symmetry) {
974	    Symmetry *conv_symmetry;
975	
976	    debug_print("get_initial_conventional_symmetry\n");
977	
978	    conv_symmetry = NULL;
979	
980	    if (centering == R_CENTER) {
981	        /* hP for rhombohedral */
982	        conv_symmetry = get_conventional_symmetry(tmat, PRIMITIVE, symmetry);
983	    } else {
