990	/* Return 0 if failed */
991	static int match_hall_symbol_db(
992	    double origin_shift[3], double conv_lattice[3][3],
993	    double const (*orig_lattice)[3], int const hall_number,
994	    int const pointgroup_number, Holohedry const holohedry,
995	    Centering const centering, Symmetry const *symmetry, double const symprec) {
996	    int is_found, num_free_axes;
997	    SpacegroupType spacegroup_type;
998	    Symmetry *changed_symmetry;
999	    double changed_lattice[3][3], inv_lattice[3][3], tmat[3][3];
1000	
1001	    changed_symmetry = NULL;
1002	
1003	    spacegroup_type = spgdb_get_spacegroup_type(hall_number);
1004	
1005	    if (pointgroup_number != spacegroup_type.pointgroup_number) {
1006	        goto err;
1007	    }
1008	
1009	    switch (holohedry) {

1009	    switch (holohedry) {
1010	        case MONOCLI:
1011	            if (match_hall_symbol_db_monocli(
1012	                    origin_shift, conv_lattice, orig_lattice, hall_number,
1013	                    spacegroup_type.number, centering, symmetry, symprec)) {
1014	                return 1;
1015	            }
1016	            break;
1017	
1018	        case ORTHO:
1019	            if (hall_number > 0) {
1020	                num_free_axes =
1021	                    num_axis_choices_ortho[spacegroup_type.number - 16];
1022	            } else if (hall_number < 0) {
1023	                num_free_axes =
1024	                    layer_num_axis_choices_ortho[spacegroup_type.number - 19];
1025	            }
1026	            assert(num_free_axes > 0);
1027	
1028	            /* Switching two axes */
1029	            /* Two steps: */
1030	            /*   1. Finding principal axis for the representative hall symbol */
1031	            /*      of the specified hall symbol without checking basis vector
1032	             */
1033	            /*      lengths preference. */
1034	            /*   2. Finding transformation matrix and origin shift for the */
1035	            /*      specified hall symbol. */
1036	            if (hall_number > 0 && num_free_axes == 2) {
1037	                mat_copy_matrix_d3(changed_lattice, conv_lattice);
1038	                if (!match_hall_symbol_db_ortho(
1039	                        origin_shift, changed_lattice, orig_lattice,
1040	                        spacegroup_to_hall_number[spacegroup_type.number - 1],
1041	                        centering, symmetry, 0, symprec)) {
1042	                    break;
1043	                }
1044	                mat_inverse_matrix_d3(inv_lattice, conv_lattice, 0);
1045	                mat_multiply_matrix_d3(tmat, inv_lattice, changed_lattice);
1046	
1047	                if ((changed_symmetry = get_conventional_symmetry(
1048	                         tmat, PRIMITIVE, symmetry)) == NULL) {
1049	                    goto err;
1050	                }
1051	
1052	                is_found = match_hall_symbol_db_ortho(
1053	                    origin_shift, changed_lattice, orig_lattice, hall_number,
1054	                    centering, changed_symmetry, 2, symprec);
1055	                sym_free_symmetry(changed_symmetry);
1056	                changed_symmetry = NULL;
1057	                if (is_found) {
1058	                    mat_copy_matrix_d3(conv_lattice, changed_lattice);
1059	                    return 1;
1060	                }
1061	                break;
1062	            }
1063	
1064	            if (match_hall_symbol_db_ortho(origin_shift, conv_lattice,
1065	                                           orig_lattice, hall_number, centering,
1066	                                           symmetry, num_free_axes, symprec)) {
1067	                return 1;
1068	            }
1069	            break;
1070	
1071	        case CUBIC:
1072	            if (match_hall_symbol_db_cubic(origin_shift, conv_lattice,
1073	                                           orig_lattice, hall_number, centering,
1074	                                           symmetry, symprec)) {
1075	                return 1;
1076	            }
1077	            break;
1078	
1079	        case TRIGO:
1080	            if ((centering == R_CENTER) &&
1081	                (hall_number == 433 || hall_number == 434 ||
1082	                 hall_number == 436 || hall_number == 437 ||
1083	                 hall_number == 444 || hall_number == 445 ||
1084	                 hall_number == 450 || hall_number == 451 ||
1085	                 hall_number == 452 || hall_number == 453 ||
1086	                 hall_number == 458 || hall_number == 459 ||
1087	                 hall_number == 460 || hall_number == 461)) {
1088	                /* Rhombohedral. symmetry is for a=b=c basis. */
1089	                if (match_hall_symbol_db_rhombo(origin_shift, conv_lattice,
1090	                                                orig_lattice, hall_number,
1091	                                                symmetry, symprec)) {
1092	                    return 1;
1093	                }
1094	                break;
1095	            }
1096	            /* Do not break for other trigonal cases */
1097	        default: /* HEXA, TETRA, TRICLI and rest of TRIGO */
1098	            if (match_hall_symbol_db_others(
1099	                    origin_shift, conv_lattice, orig_lattice, hall_number,
1100	                    centering, holohedry, symmetry, symprec)) {
1101	                return 1;
1102	            }
1103	            break;
1104	    }
1105	
1106	err:
1107	    return 0;
1108	}

