347	Pointgroup ptg_get_transformation_matrix(int transform_mat[3][3],
348	                                         int const rotations[][3][3],
349	                                         int const num_rotations,
350	                                         int const aperiodic_axis) {
351	    int i, j, pg_num;
352	    int axes[3];
353	    PointSymmetry pointsym;
354	    Pointgroup pointgroup;
355	
356	    debug_print("ptg_get_transformation_matrix:\n");
357	
358	    for (i = 0; i < 3; i++) {
359	        for (j = 0; j < 3; j++) {
360	            transform_mat[i][j] = 0;
361	        }
362	    }
363	
364	    pg_num = get_pointgroup_number_by_rotations(rotations, num_rotations);
365	
366	    // Layer group does not have cubic point groups (28 <= pg_num < 32)
367	    if (pg_num > 0 && (aperiodic_axis == -1 || pg_num < 28)) {
368	        // Based on step (c) of R. W. Grosse-Kunstleve (1999)
369	        pointgroup = ptg_get_pointgroup(pg_num);
370	        pointsym = ptg_get_pointsymmetry(rotations, num_rotations);
371	        get_axes(axes, pointgroup.laue, &pointsym, aperiodic_axis);
372	        set_transformation_matrix(transform_mat, axes);
373	    } else {
374	        info_print("spglib: No point group was found\n");
375	        pointgroup.number = 0;
376	    }
377	
378	    return pointgroup;
379	}
