381	Pointgroup ptg_get_pointgroup(int const pointgroup_number) {
382	    int i;
383	    Pointgroup pointgroup;
384	    PointgroupType pointgroup_type;
385	
386	    pointgroup.number = pointgroup_number;
387	    pointgroup_type = pointgroup_data[pointgroup_number];
388	    memcpy(pointgroup.symbol, pointgroup_type.symbol, 6);
389	    memcpy(pointgroup.schoenflies, pointgroup_type.schoenflies, 4);
390	    for (i = 0; i < 5; i++) {
391	        if (pointgroup.symbol[i] == ' ') {
392	            pointgroup.symbol[i] = '\0';
393	        }
394	    }
395	    for (i = 0; i < 3; i++) {
396	        if (pointgroup.schoenflies[i] == ' ') {
397	            pointgroup.schoenflies[i] = '\0';
398	        }
399	    }
400	    pointgroup.holohedry = pointgroup_type.holohedry;
401	    pointgroup.laue = pointgroup_type.laue;
402	
403	    debug_print("ptg_get_pointgroup: %s\n", pointgroup_type.symbol);
404	
405	    return pointgroup;
406	}
