408	// @brief Construct PointSymmetry from given `rotations`
409	PointSymmetry ptg_get_pointsymmetry(int const rotations[][3][3],
410	                                    int const num_rotations) {
411	    int i, j;
412	    PointSymmetry pointsym;
413	
414	    pointsym.size = 0;
415	    for (i = 0; i < num_rotations; i++) {
416	        for (j = 0; j < pointsym.size; j++) {
417	            if (mat_check_identity_matrix_i3(rotations[i], pointsym.rot[j])) {
418	                goto escape;
419	            }
420	        }
421	        mat_copy_matrix_i3(pointsym.rot[pointsym.size], rotations[i]);
422	        pointsym.size++;
423	    escape:;
424	    }
425	
426	    return pointsym;
427	}
