437	static int get_pointgroup_number(PointSymmetry const* pointsym) {
438	    int i, j, pg_num, counter;
439	    int table[10];
440	    PointgroupType pointgroup_type;
441	
442	    debug_print("get_pointgroup_number:");
443	
444	    pg_num = 0;
445	
446	    /* Get list of point symmetry operations */
447	    if (!get_pointgroup_class_table(table, pointsym)) {
448	        goto end;
449	    }
450	
451	    for (i = 1; i < 33; i++) {
452	        counter = 0;
453	        pointgroup_type = pointgroup_data[i];
454	        for (j = 0; j < 10; j++) {
455	            if (pointgroup_type.table[j] == table[j]) {
456	                counter++;
457	            }
458	        }
459	        if (counter == 10) {
460	            pg_num = i;
461	            break;
462	        }
463	    }
464	
465	end:
466	    debug_print(" %d\n", pg_num);
467	    return pg_num;
468	}
