513	static int get_rotation_type(int const rot[3][3]) {
514	    int rot_type;
515	
516	    if (mat_get_determinant_i3(rot) == -1) {
517	        switch (mat_get_trace_i3(rot)) {
518	            case -2: /* -6 */
519	                rot_type = 0;
520	                break;
521	            case -1: /* -4 */
522	                rot_type = 1;
523	                break;
524	            case 0: /* -3 */
525	                rot_type = 2;
526	                break;
527	            case 1: /* -2 */
528	                rot_type = 3;
529	                break;
530	            case -3: /* -1 */
531	                rot_type = 4;
532	                break;
533	            default:
534	                rot_type = -1;
535	                break;
536	        }
537	    } else {
538	        switch (mat_get_trace_i3(rot)) {
539	            case 3: /* 1 */
540	                rot_type = 5;
541	                break;
542	            case -1: /* 2 */
543	                rot_type = 6;
544	                break;
545	            case 0: /* 3 */
546	                rot_type = 7;
547	                break;
548	            case 1: /* 4 */
549	                rot_type = 8;
550	                break;
551	            case 2: /* 6 */
552	                rot_type = 9;
553	                break;
554	            default:
555	                rot_type = -1;
556	                break;
557	        }
558	    }
559	
560	    return rot_type;
561	}
