563	// @brief Get conventional axes for point group `pointsym`
564	// @note For layer group, Laue class 2/m and mmm need a special care
565	// @param[out] axes three indices of `rot_axes`. If they are larger than
566	//             NUM_ROT_AXES, it represents the negative direction.
567	// @param[in] laue
568	// @param[in] pointsym
569	// @param[in] aperiodic_axis
570	static int get_axes(int axes[3], Laue const laue, PointSymmetry const* pointsym,
571	                    int const aperiodic_axis) {
572	    switch (laue) {
573	        case LAUE1:
574	            axes[0] = 0;  // {1, 0, 0}
575	            axes[1] = 1;  // {0, 1, 0}
576	            axes[2] = 2;  // {0, 0, 1}
577	            break;
578	        case LAUE2M:
579	            if (aperiodic_axis == -1) {
580	                laue2m(axes, pointsym);
581	            } else {
582	                layer_laue2m(axes, pointsym, aperiodic_axis);
583	            }
584	            break;
585	        case LAUEMMM:
586	            lauennn(axes, pointsym, 2, aperiodic_axis);
587	            break;
588	        case LAUE4M:
589	            laue_one_axis(axes, pointsym, 4);
590	            break;
591	        case LAUE4MMM:
592	            laue_one_axis(axes, pointsym, 4);
593	            break;
594	        case LAUE3:
595	            laue_one_axis(axes, pointsym, 3);
596	            break;
597	        case LAUE3M:
598	            laue_one_axis(axes, pointsym, 3);
599	            break;
600	        case LAUE6M:
601	            laue_one_axis(axes, pointsym, 3);
602	            break;
603	        case LAUE6MMM:
604	            laue_one_axis(axes, pointsym, 3);
605	            break;
606	        case LAUEM3:
607	            lauennn(axes, pointsym, 2, -1);
608	            break;
609	        case LAUEM3M:
610	            lauennn(axes, pointsym, 4, -1);
611	            break;
612	        default:
613	            break;
614	    }
615	
616	    return 1;
617	}
618	
619	static int laue2m(int axes[3], PointSymmetry const* pointsym) {
620	    int i, num_ortho_axis, norm, min_norm, is_found;
621	    int prop_rot[3][3];
622	    int ortho_axes[NUM_ROT_AXES];
623	    /* Uncomment to pass original POSCAR-14-227-47-ref,
624	     * POSCAR-15-230-prim-18-ref, POSCAR-15-bcc-18-ref */
625	    /* This has been done in 2D delaunay reduce
626	    int tmpval, t_mat[3][3];
627	    */
628	
629	    for (i = 0; i < pointsym->size; i++) {
630	        get_proper_rotation(prop_rot, pointsym->rot[i]);
631	
632	        /* Search two-fold rotation */
633	        if (!(mat_get_trace_i3(prop_rot) == -1)) {
634	            continue;
635	        }
636	
637	        /* The first axis (unique axis b) */
638	        axes[1] = get_rotation_axis(prop_rot);
639	        break;
640	    }
641	
642	    /* The second axis */
643	    num_ortho_axis = get_orthogonal_axis(ortho_axes, prop_rot, 2);
644	    if (!num_ortho_axis) {
645	        goto err;
646	    }
647	
648	    min_norm = 8;
649	    is_found = 0;
650	    for (i = 0; i < num_ortho_axis; i++) {
651	        norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
652	        if (norm < min_norm) {
653	            min_norm = norm;
654	            axes[0] = ortho_axes[i];
655	            is_found = 1;
656	        }
657	    }
658	    if (!is_found) {
659	        goto err;
660	    }
661	
662	    /* The third axis */
663	    min_norm = 8;
664	    is_found = 0;
665	    for (i = 0; i < num_ortho_axis; i++) {
666	        norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
667	        if ((norm < min_norm) && (ortho_axes[i] != axes[0])) {
668	            min_norm = norm;
669	            axes[2] = ortho_axes[i];
670	            is_found = 1;
671	        }
672	    }
673	    if (!is_found) {
674	        goto err;
675	    }
676	
677	    /* Uncomment to pass original POSCAR-14-227-47-ref,
678	     * POSCAR-15-230-prim-18-ref, POSCAR-15-bcc-18-ref */
679	    /* This has been done in 2D delaunay reduce
680	    set_transformation_matrix(t_mat, axes);
681	    if (mat_get_determinant_i3(t_mat) < 0) {
682	      tmpval = axes[0];
683	      axes[0] = axes[2];
684	      axes[2] = tmpval;
685	    }
686	    */
687	
688	    return 1;
689	
690	err:
691	    return 0;
692	}
693	
694	// @note The two-fold axis is set to axis-a. Axes b and c forms the periodic
695	// plane.
696	static int layer_laue2m(int axes[3], PointSymmetry const* pointsym,
697	                        int const aperiodic_axis) {
698	    int i, num_ortho_axis, norm, min_norm, is_found;
699	    int prop_rot[3][3];
700	    int ortho_axes[NUM_ROT_AXES];
701	
702	    for (i = 0; i < pointsym->size; i++) {
703	        get_proper_rotation(prop_rot, pointsym->rot[i]);
704	
705	        /* Search two-fold rotation */
706	        if (!(mat_get_trace_i3(prop_rot) == -1)) {
707	            continue;
708	        }
709	
710	        /* Monoclinic/Rectangular: The first axis is axis a according to ITE */
711	        /* Monoclinic/Oblique: The first axis is moved to c in
712	         * change_basis_monocli */
713	        axes[0] = get_rotation_axis(prop_rot);
714	        break;
715	    }
716	
717	    num_ortho_axis = get_orthogonal_axis(ortho_axes, prop_rot, 2);
718	    if (!num_ortho_axis) {
719	        goto err;
720	    }
721	
722	    if (rot_axes[axes[0]][aperiodic_axis] == 1 ||
723	        rot_axes[axes[0]][aperiodic_axis] == -1) {
724	        /* For Monoclinic/Oblique. */
725	        /* The second axis */
726	        min_norm = 8;
727	        is_found = 0;
728	        for (i = 0; i < num_ortho_axis; i++) {
729	            norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
730	            if (norm < min_norm) {
731	                min_norm = norm;
732	                axes[1] = ortho_axes[i];
733	                is_found = 1;
734	            }
735	        }
736	        if (!is_found) {
737	            goto err;
738	        }
739	
740	        /* The third axis */
741	        min_norm = 8;
742	        is_found = 0;
743	        for (i = 0; i < num_ortho_axis; i++) {
744	            norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
745	            if ((norm < min_norm) && (ortho_axes[i] != axes[1])) {
746	                min_norm = norm;
747	                axes[2] = ortho_axes[i];
748	                is_found = 1;
749	            }
750	        }
751	        if (!is_found) {
752	            goto err;
753	        }
754	    } else if (rot_axes[axes[0]][aperiodic_axis] == 0) {
755	        /* For Monoclinic/Rectangular. */
756	        /* The second axis in the periodic plane */
757	        min_norm = 8;
758	        is_found = 0;
759	        for (i = 0; i < num_ortho_axis; i++) {
760	            if (rot_axes[ortho_axes[i]][aperiodic_axis] == 0) {
761	                norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
762	                if (norm < min_norm) {
763	                    min_norm = norm;
764	                    axes[1] = ortho_axes[i];
765	                    is_found = 1;
766	                }
767	            }
768	        }
769	        if (!is_found) {
770	            goto err;
771	        }
772	
773	        /* The third axis outside the periodic plane */
774	        min_norm = 8;
775	        is_found = 0;
776	        for (i = 0; i < num_ortho_axis; i++) {
777	            if (rot_axes[ortho_axes[i]][aperiodic_axis] == 1 ||
778	                rot_axes[ortho_axes[i]][aperiodic_axis] == -1) {
779	                norm = mat_norm_squared_i3(rot_axes[ortho_axes[i]]);
780	                if (norm < min_norm) {
781	                    min_norm = norm;
782	                    axes[2] = ortho_axes[i];
783	                    is_found = 1;
784	                }
785	            }
786	        }
787	        if (!is_found) {
788	            goto err;
789	        }
790	    } else {
791	        goto err;
792	    }
793	
794	    /* det(t_mat) > 0 in 2D delaunay reduce */
795	
796	    return 1;
797	
798	err:
799	    return 0;
800	}
