802	// For Laue classes 4/m, 4/mmm, -3, -3/m, 6/m, 6/mmm
803	static int laue_one_axis(int axes[3], PointSymmetry const* pointsym,
804	                         int const rot_order) {
805	    int i, j, num_ortho_axis, det, is_found, tmpval;
806	    int axis_vec[3], tmp_axes[3];
807	    int prop_rot[3][3], t_mat[3][3];
808	    int ortho_axes[NUM_ROT_AXES];
809	
810	    debug_print("laue_one_axis with rot_order %d\n", rot_order);
811	
812	    for (i = 0; i < pointsym->size; i++) {
813	        get_proper_rotation(prop_rot, pointsym->rot[i]);
814	
815	        /* Search four-fold rotation */
816	        if (rot_order == 4) {
817	            if (mat_get_trace_i3(prop_rot) == 1) {
818	                /* The first axis (c axis) */

819	                axes[2] = get_rotation_axis(prop_rot);
820	                break;
821	            }
822	        }
823	
824	        /* Search three-fold rotation */
825	        if (rot_order == 3) {
826	            if (mat_get_trace_i3(prop_rot) == 0) {
827	                /* The first axis (c axis) */
828	                axes[2] = get_rotation_axis(prop_rot);
829	                break;
830	            }
831	        }
832	    }
833	
834	    /* Candidates of the second axis */
835	    num_ortho_axis = get_orthogonal_axis(ortho_axes, prop_rot, rot_order);
836	    if (!num_ortho_axis) {
837	        goto err;
838	    }
839	
840	    tmp_axes[1] = -1;
841	    tmp_axes[2] = axes[2];
842	    for (i = 0; i < num_ortho_axis; i++) {
843	        is_found = 0;
844	        tmp_axes[0] = ortho_axes[i];
845	        mat_multiply_matrix_vector_i3(axis_vec, prop_rot,
846	                                      rot_axes[tmp_axes[0]]);
847	        for (j = 0; j < num_ortho_axis; j++) {
848	            is_found = is_exist_axis(axis_vec, ortho_axes[j]);
849	            if (is_found == 1) {
850	                tmp_axes[1] = ortho_axes[j];
851	                break;
852	            }
853	            if (is_found == -1) {
854	                tmp_axes[1] = ortho_axes[j] + NUM_ROT_AXES;
855	                break;
856	            }
857	        }
858	
859	        if (!is_found) {
860	            continue;
861	        }
862	
863	        set_transformation_matrix(t_mat, tmp_axes);
864	        det = abs(mat_get_determinant_i3(t_mat));
865	        if (det < 4) { /* to avoid F-center choice det=4 */
866	            axes[0] = tmp_axes[0];
867	            axes[1] = tmp_axes[1];
868	            goto end;
869	        }
870	    }
871	
872	err: /* axes are not correctly found. */
873	    warning_print("spglib: Secondary axis is not found.\n");
874	    return 0;
875	
876	end:
877	    set_transformation_matrix(t_mat, axes);
878	    if (mat_get_determinant_i3(t_mat) < 0) {
879	        tmpval = axes[0];
880	        axes[0] = axes[1];
881	        axes[1] = tmpval;
882	    }
883	
884	    debug_print("axes[0] = %d\n", axes[0]);
885	    debug_print("axes[1] = %d\n", axes[1]);
886	    debug_print("axes[2] = %d\n", axes[2]);
887	
888	    return 1;
889	}
