891	// For Laue classes mmm, m-3, m-3m
892	static int lauennn(int axes[3], PointSymmetry const* pointsym,
893	                   int const rot_order, int const aperiodic_axis) {
894	    int i, count, axis;
895	    int prop_rot[3][3];
896	
897	    for (i = 0; i < 3; i++) {
898	        axes[i] = -1;
899	    }
900	
901	    count = 0;
902	    for (i = 0; i < pointsym->size; i++) {
