#include <math.h>
#include <stdio.h>
#include <stdlib.h>

#include "delaunay.h"
#include "mathfunc.h"
#include "pointgroup.h"
#include "primitive.h"
#include "spacegroup.h"
#include "symmetry.h"

static void build_lattice(double lattice[3][3], double const a, double const b,
                          double const c, double const alpha, double const beta,
                          double const gamma) {
    int i, j;
    double cx, cy, cz2;
    double const sg = sin(gamma);
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++) lattice[i][j] = 0;
    lattice[0][0] = a;
    lattice[0][1] = b * cos(gamma);
    lattice[1][1] = b * sg;
    cx = c * cos(beta);
    cy = c * (cos(alpha) - cos(beta) * cos(gamma)) / sg;
    cz2 = c * c - cx * cx - cy * cy;
    lattice[0][2] = cx;
    lattice[1][2] = cy;
    lattice[2][2] = sqrt(cz2);
}

static void run_case(char const *name, int const rotations[][3][3],
                     double const translations[][3], int const num_ops,
                     double const len[3], double const ang[3]) {
    double lattice[3][3], prim_lat[3][3], red_lat[3][3];
    double invL[3][3], T[3][3], Ti[3][3], tmp[3][3], rd[3][3];
    double const symprec = 0.01;
    double const pi = 4 * atan(1.0);
    Symmetry *sym, *red;
    Spacegroup *sg;
    int i, j, k;

    printf("==== %s ====\n", name);
    build_lattice(lattice, len[0], len[1], len[2], ang[0] * pi / 180,
                  ang[1] * pi / 180, ang[2] * pi / 180);

    sym = sym_alloc_symmetry(num_ops);
    for (i = 0; i < num_ops; i++) {
        for (j = 0; j < 3; j++) {
            for (k = 0; k < 3; k++) sym->rot[i][j][k] = rotations[i][j][k];
            sym->trans[i][j] = translations[i][j];
        }
    }

    mat_copy_matrix_d3(prim_lat, lattice);
    if (!del_delaunay_reduce(red_lat, prim_lat, symprec)) {
        printf("reduction failed\n");
        return;
    }
    printf("reduced lattice:\n");
    for (j = 0; j < 3; j++)
        printf("  %8.4f %8.4f %8.4f\n", red_lat[j][0], red_lat[j][1], red_lat[j][2]);

    /* red_lat = L * T ; ops' = T^-1 ops T */
    mat_inverse_matrix_d3(invL, prim_lat, 0);
    mat_multiply_matrix_d3(T, invL, red_lat);
    mat_inverse_matrix_d3(Ti, T, 0);
    printf("T (=L^-1 red): \n");
    for (j = 0; j < 3; j++)
        printf("  %8.4f %8.4f %8.4f\n", T[j][0], T[j][1], T[j][2]);

    red = sym_alloc_symmetry(num_ops);
    for (i = 0; i < num_ops; i++) {
        for (j = 0; j < 3; j++)
            for (k = 0; k < 3; k++) rd[j][k][0] = 0;
        mat_cast_matrix_3i_to_3d(rd, sym->rot[i]);
        mat_multiply_matrix_d3(tmp, Ti, rd);
        mat_multiply_matrix_d3(rd, tmp, T);
        mat_cast_matrix_3d_to_3i(red->rot[i], rd);
        /* also sanity: how non-integral */
        {
            double err = 0;
            for (j = 0; j < 3; j++)
                for (k = 0; k < 3; k++) {
                    double d = rd[j][k] - red->rot[i][j][k];
                    if (d < 0) d = -d;
                    if (d > err) err = d;
                }
            /* translation */
            double tv[3];
            mat_multiply_matrix_vector_d3(tv, Ti, sym->trans[i]);
            red->trans[i][0] = tv[0]; red->trans[i][1] = tv[1]; red->trans[i][2] = tv[2];
            if (err > 1e-6) printf("op %d rotation non-integral err=%g\n", i, err);
        }
    }
    for (i = 0; i < num_ops; i++) {
        printf("op %d: rot=(%d %d %d / %d %d %d / %d %d %d) t=(%.4f %.4f %.4f)\n", i,
               red->rot[i][0][0], red->rot[i][0][1], red->rot[i][0][2],
               red->rot[i][1][0], red->rot[i][1][1], red->rot[i][1][2],
               red->rot[i][2][0], red->rot[i][2][1], red->rot[i][2][2],
               red->trans[i][0], red->trans[i][1], red->trans[i][2]);
    }

    sg = spa_search_spacegroup_with_symmetry(red, red_lat, symprec);
    if (sg) {
        printf("RESULT-reduced hall=%d number=%d international=%s choice=%s\n",
               sg->hall_number, sg->number, sg->international, sg->choice);
        free(sg);
    } else {
        printf("RESULT-reduced search failed\n");
    }

    sym_free_symmetry(sym);
    sym_free_symmetry(red);
}

