    /* The space-group-type identification has to be invariant under a change
     * of the representation of the same crystal.  The search is therefore
     * first attempted in the Delaunay-reduced setting, which is a canonical
     * description of the given primitive lattice.  If that fails, the search
     * in the given setting is attempted as a fallback. */
    spacegroup = search_spacegroup_in_reduced_setting(prim_symmetry, prim_lat,
                                                      symprec);
    if (spacegroup == NULL) {
        spacegroup = spa_search_spacegroup_with_symmetry(prim_symmetry,
                                                         prim_lat, symprec);
    }
    sym_free_symmetry(prim_symmetry);
    prim_symmetry = NULL;
    if (spacegroup) {
        hall_number = spacegroup->hall_number;
        free(spacegroup);
        spacegroup = NULL;
    } else {
        goto err;
    }

    return hall_number;

err:
    return 0;
}

/* Return NULL if failed. */
/* The given lattice is brought into the Delaunay-reduced setting and the */
/* symmetry operations are transformed coherently, (R, t) -> (P^-1.R.P, */
/* P^-1.t), into that basis.  The search for the space-group type is then */
/* representation-independent because equivalent crystal descriptions are */
/* mapped to an identical reduced setting. */
static Spacegroup *search_spacegroup_in_reduced_setting(
    Symmetry const *symmetry, double const lattice[3][3],
    double const symprec) {
    int i, j;
    Symmetry *red_symmetry;
    Spacegroup *spacegroup;
    double red_lat[3][3], inv_lat[3][3], t_red[3][3], t_red_inv[3][3];
    double rot_d[3][3];

    red_symmetry = NULL;
    spacegroup = NULL;

    if (!del_delaunay_reduce(red_lat, lattice, symprec)) {
        goto ret;
    }

    /* The space-group-type search assumes a right-handed lattice basis. */
    if (mat_get_determinant_d3(red_lat) < 0) {
        for (i = 0; i < 3; i++) {
            for (j = 0; j < 3; j++) {
                red_lat[i][j] = -red_lat[i][j];
            }
        }
    }

    /* red_lat = lattice @ t_red */
    if (!mat_inverse_matrix_d3(inv_lat, lattice, 0)) {
        goto ret;
    }
    mat_multiply_matrix_d3(t_red, inv_lat, red_lat);
    if (!mat_inverse_matrix_d3(t_red_inv, t_red, 0)) {
        goto ret;
    }

    if ((red_symmetry = sym_alloc_symmetry(symmetry->size)) == NULL) {
        goto ret;
    }
    for (i = 0; i < symmetry->size; i++) {
        mat_cast_matrix_3i_to_3d(rot_d, symmetry->rot[i]);
        /* rot -> t_red^-1.rot.t_red, trans -> t_red^-1.trans */
        if (!mat_get_similar_matrix_d3(rot_d, rot_d, t_red, 0)) {
            goto ret;
        }
        mat_cast_matrix_3d_to_3i(red_symmetry->rot[i], rot_d);
        mat_multiply_matrix_vector_d3(red_symmetry->trans[i], t_red_inv,
                                      symmetry->trans[i]);
    }

    spacegroup =
        spa_search_spacegroup_with_symmetry(red_symmetry, red_lat, symprec);

ret:
    if (red_symmetry) {
        sym_free_symmetry(red_symmetry);
        red_symmetry = NULL;
    }

    return spacegroup;
}

