    double lattice[3][3] = {{2.456, 0, 0}, {0, 0, 0}, {0, 0, 6.696}};
    double position[4][3] = {{0, 0, 0.25}, {0, 0, 0.75}, {1.0 / 3, 2.0 / 3, 0.25}, {2.0 / 3, 1.0 / 3, 0.75}};
